def v63_summary():
    p=V63_DIR/"full"/"jlaw_v6_trades.csv"
    if not p.exists() or p.stat().st_size==0:return {"available":False}
    try:T=pd.read_csv(p)
    except Exception:return {"available":False}
    if T.empty:return {"available":False}
    rows=[]
    def add(name,g):
        if g is None or g.empty:return
        m=_v6_shadow_metrics(g)
        rows.append({"name":name,**m})
    add("ALL V6.3",T)
    if "v6_market_character" in T.columns:
        add("POWER_TREND",T[T["v6_market_character"].astype(str)=="POWER_TREND"])
    if "rs" in T.columns:
        add("RS2 ≥90",T[pd.to_numeric(T["rs"],errors="coerce")>=90])
        add("RS2 90–95",T[(pd.to_numeric(T["rs"],errors="coerce")>=90)&(pd.to_numeric(T["rs"],errors="coerce")<95)])
        add("RS2 ≥95",T[pd.to_numeric(T["rs"],errors="coerce")>=95])
    if "volratio" in T.columns and "rs" in T.columns and "v6_market_character" in T.columns:
        m=(T["v6_market_character"].astype(str)=="POWER_TREND")&(pd.to_numeric(T["volratio"],errors="coerce")>=1.8)&(pd.to_numeric(T["rs"],errors="coerce")>=90)
        add("POWER + Vol≥1.8x + RS2≥90",T[m])

    eras=[]; recent=[]; rsbands=[]
    if "date" in T.columns:
        T["date"]=pd.to_datetime(T["date"],errors="coerce")
        for nm,st,en in [("2007–2011","2007-01-01","2011-12-31"),("2012–2016","2012-01-01","2016-12-31"),
                         ("2017–2021","2017-01-01","2021-12-31"),("2022–2026","2022-01-01","2026-12-31")]:
            g=T[(T["date"]>=pd.Timestamp(st))&(T["date"]<=pd.Timestamp(en))]
            if len(g): eras.append({"name":nm,**_v6_shadow_metrics(g)})

        R=T[(T["date"]>=pd.Timestamp("2022-01-01"))&(T["date"]<=pd.Timestamp("2026-12-31"))].copy()
        if len(R):
            def radd(nm,g):
                if len(g): recent.append({"name":nm,**_v6_shadow_metrics(g)})
            radd("2022–26 ALL",R)
            if "v6_market_character" in R.columns:
                radd("2022–26 POWER",R[R["v6_market_character"].astype(str)=="POWER_TREND"])
            if "rs" in R.columns:
                rr=pd.to_numeric(R["rs"],errors="coerce")
                radd("2022–26 RS2≥90",R[rr>=90])
            if all(c in R.columns for c in ["v6_market_character","rs","volratio"]):
                rr=pd.to_numeric(R["rs"],errors="coerce"); vv=pd.to_numeric(R["volratio"],errors="coerce")
                mm=(R["v6_market_character"].astype(str)=="POWER_TREND")&(rr>=90)&(vv>=1.8)
                radd("2022–26 POWER+Vol≥1.8+RS2≥90",R[mm])

    if "rs" in T.columns:
        rr=pd.to_numeric(T["rs"],errors="coerce")
        for nm,lo,hi in [("<80",None,80),("80–90",80,90),("90–95",90,95),("95–98",95,98),("98–100",98,100.0001)]:
            m=pd.Series(True,index=T.index)
            if lo is not None:m &= rr>=lo
            if hi is not None:m &= rr<hi
            g=T[m]
            if len(g): rsbands.append({"name":nm,**_v6_shadow_metrics(g)})

    cohort_rows=[]
    recent_rs2_bands=[]

    # Split by original research cohort vs validation cohort using ticker lists already defined in app.
    if "ticker" in T.columns:
        tick=T["ticker"].astype(str)
        original_set=set(V5_ORIGINAL_122)
        validation_set=set(V5_VALIDATION)
        cohort_defs=[
            ("ORIGINAL_122", T[tick.isin(original_set)]),
            ("VALIDATION_324", T[tick.isin(validation_set)]),
        ]
        for cname,C in cohort_defs:
            if C.empty: continue
            def cadd(label,g):
                if len(g): cohort_rows.append({"cohort":cname,"name":label,**_v6_shadow_metrics(g)})
            cadd("ALL",C)
            if "v6_market_character" in C.columns:
                cadd("POWER",C[C["v6_market_character"].astype(str)=="POWER_TREND"])
            if "rs" in C.columns:
                rr=pd.to_numeric(C["rs"],errors="coerce")
                cadd("RS2≥90",C[rr>=90])
            if all(c in C.columns for c in ["v6_market_character","rs","volratio"]):
                rr=pd.to_numeric(C["rs"],errors="coerce")
                vv=pd.to_numeric(C["volratio"],errors="coerce")
                mm=(C["v6_market_character"].astype(str)=="POWER_TREND")&(rr>=90)&(vv>=1.8)
                cadd("POWER+Vol≥1.8+RS2≥90",C[mm])

    # Recent-era non-overlapping RS2 bands.
    if "date" in T.columns and "rs" in T.columns:
        R=T[(T["date"]>=pd.Timestamp("2022-01-01"))&(T["date"]<=pd.Timestamp("2026-12-31"))].copy()
        if len(R):
            rr=pd.to_numeric(R["rs"],errors="coerce")
            for nm,lo,hi in [("<80",None,80),("80–90",80,90),("90–95",90,95),("95–98",95,98),("98–100",98,100.0001)]:
                m=pd.Series(True,index=R.index)
                if lo is not None:m &= rr>=lo
                if hi is not None:m &= rr<hi
                g=R[m]
                if len(g): recent_rs2_bands.append({"name":nm,**_v6_shadow_metrics(g)})

    validation_core=[]
    validation_core_eras=[]

    # V6.3.7: drill into the validation cohort CORE candidate only.
    # Candidate = VALIDATION_324 + POWER_TREND + volratio>=1.8 + RS2>=90.
    if "ticker" in T.columns:
        tick=T["ticker"].astype(str)
        V=T[tick.isin(set(V5_VALIDATION))].copy()

        if all(c in V.columns for c in ["v6_market_character","volratio","rs"]):
            vv=pd.to_numeric(V["volratio"],errors="coerce")
            rr=pd.to_numeric(V["rs"],errors="coerce")
            base=(V["v6_market_character"].astype(str)=="POWER_TREND")&(vv>=1.8)&(rr>=90)
            C=V[base].copy()

            def vcadd(group,label,g):
                if len(g):
                    validation_core.append({"group":group,"name":label,**_v6_shadow_metrics(g)})

            vcadd("BASE","ALL CORE",C)

            # Non-overlapping Volume buckets
            if "volratio" in C.columns:
                cv=pd.to_numeric(C["volratio"],errors="coerce")
                for nm,lo,hi in [("1.8–2.0x",1.8,2.0),("2.0–2.5x",2.0,2.5),("2.5x+",2.5,None)]:
                    m=cv>=lo
                    if hi is not None:m &= cv<hi
                    vcadd("VOLUME",nm,C[m])

            # Non-overlapping RS2 buckets
            if "rs" in C.columns:
                cr=pd.to_numeric(C["rs"],errors="coerce")
                for nm,lo,hi in [("90–92",90,92),("92–95",92,95),("95–98",95,98),("98–100",98,100.0001)]:
                    vcadd("RS2",nm,C[(cr>=lo)&(cr<hi)])

            # Supply buckets
            if "supply_score" in C.columns:
                cs=pd.to_numeric(C["supply_score"],errors="coerce")
                for nm,lo,hi in [("<55",None,55),("55–65",55,65),("65–75",65,75),("75+",75,None)]:
                    m=pd.Series(True,index=C.index)
                    if lo is not None:m &= cs>=lo
                    if hi is not None:m &= cs<hi
                    vcadd("SUPPLY",nm,C[m])

            # Entry extension buckets
            if "extension" in C.columns:
                ce=pd.to_numeric(C["extension"],errors="coerce")
                for nm,lo,hi in [("≤1%",None,0.01),("1–2%",0.01,0.02),("2–3%",0.02,0.03),(">3%",0.03,None)]:
                    m=pd.Series(True,index=C.index)
                    if lo is not None:m &= ce>lo
                    if hi is not None:m &= ce<=hi
                    vcadd("ENTRY",nm,C[m])

            # Sector buckets
            if "sector_score" in C.columns:
                cs=pd.to_numeric(C["sector_score"],errors="coerce")
                for nm,lo,hi in [("<60",None,60),("60–65",60,65),("65–70",65,70),("70+",70,None)]:
                    m=pd.Series(True,index=C.index)
                    if lo is not None:m &= cs>=lo
                    if hi is not None:m &= cs<hi
                    vcadd("SECTOR",nm,C[m])

            # Group breadth buckets
            if "group_breadth" in C.columns:
                cg=pd.to_numeric(C["group_breadth"],errors="coerce")
                for nm,lo,hi in [("<40",None,40),("40–50",40,50),("50–60",50,60),("60+",60,None)]:
                    m=pd.Series(True,index=C.index)
                    if lo is not None:m &= cg>=lo
                    if hi is not None:m &= cg<hi
                    vcadd("GROUP",nm,C[m])

            # Era stability for this exact validation-core candidate
            if "date" in C.columns:
                C["date"]=pd.to_datetime(C["date"],errors="coerce")
                for nm,st,en in [("2007–2011","2007-01-01","2011-12-31"),
                                 ("2012–2016","2012-01-01","2016-12-31"),
                                 ("2017–2021","2017-01-01","2021-12-31"),
                                 ("2022–2026","2022-01-01","2026-12-31")]:
                    g=C[(C["date"]>=pd.Timestamp(st))&(C["date"]<=pd.Timestamp(en))]
                    if len(g):
                        validation_core_eras.append({"name":nm,**_v6_shadow_metrics(g)})

    validation_core_recent_trades=[]
    validation_core_feature_compare=[]

    if "ticker" in T.columns:
        tick=T["ticker"].astype(str)
        V=T[tick.isin(set(V5_VALIDATION))].copy()
        if all(c in V.columns for c in ["v6_market_character","volratio","rs"]):
            vv=pd.to_numeric(V["volratio"],errors="coerce")
            rr=pd.to_numeric(V["rs"],errors="coerce")
            C=V[(V["v6_market_character"].astype(str)=="POWER_TREND")&(vv>=1.8)&(rr>=90)].copy()

            if "date" in C.columns:
                C["date"]=pd.to_datetime(C["date"],errors="coerce")
                R=C[(C["date"]>=pd.Timestamp("2022-01-01"))&(C["date"]<=pd.Timestamp("2026-12-31"))].copy()
                for _,r in R.sort_values("date").iterrows():
                    item={}
                    for c in ["ticker","date","return_pct","volratio","rs","rs_raw","supply_score",
                              "sector_score","leader_score","group_breadth","extension",
                              "v6_edge_count","v6_red_count","v6_tier","v6_rank"]:
                        if c in R.columns:
                            v=r.get(c)
                            if c=="date":
                                item[c]=v.strftime("%Y-%m-%d") if pd.notna(v) else ""
                            elif isinstance(v,(int,float)) and pd.isna(v):
                                item[c]=None
                            else:
                                item[c]=v
                    validation_core_recent_trades.append(item)

                early=C[C["date"]<pd.Timestamp("2022-01-01")]
                recentc=C[C["date"]>=pd.Timestamp("2022-01-01")]
                for c in ["volratio","rs","rs_raw","supply_score","sector_score","leader_score",
                          "group_breadth","extension","v6_edge_count","v6_red_count"]:
                    if c not in C.columns: continue
                    def _med(df):
                        s=pd.to_numeric(df[c],errors="coerce").dropna()
                        return float(s.median()) if len(s) else None
                    validation_core_feature_compare.append({
                        "feature":c,"early":_med(early),"recent":_med(recentc)
                    })

    context_veto=[]
    context_veto_recent=[]

    # V6.3.9 Context Veto Diagnostic
    if "ticker" in T.columns:
        tick=T["ticker"].astype(str)
        V=T[tick.isin(set(V5_VALIDATION))].copy()
        if all(c in V.columns for c in ["v6_market_character","volratio","rs"]):
            vv=pd.to_numeric(V["volratio"],errors="coerce")
            rr=pd.to_numeric(V["rs"],errors="coerce")
            C=V[(V["v6_market_character"].astype(str)=="POWER_TREND")&(vv>=1.8)&(rr>=90)].copy()

            def cvadd(group,label,g,target):
                if len(g):
                    target.append({"group":group,"name":label,**_v6_shadow_metrics(g)})

            # Tier
            if "v6_tier" in C.columns:
                for nm in ["A1","A2","B","WATCH","REJECT"]:
                    cvadd("TIER",nm,C[C["v6_tier"].astype(str)==nm],context_veto)

            # Edge count
            if "v6_edge_count" in C.columns:
                ec=pd.to_numeric(C["v6_edge_count"],errors="coerce")
                for nm,lo,hi in [("≤5",None,5.0001),("6",5.999,6.001),("7",6.999,7.001),("8+",8,None)]:
                    m=pd.Series(True,index=C.index)
                    if lo is not None:m &= ec>=lo
                    if hi is not None:m &= ec<hi
                    cvadd("EDGE",nm,C[m],context_veto)

            # Supply + Extension veto candidates
            if "supply_score" in C.columns:
                ss=pd.to_numeric(C["supply_score"],errors="coerce")
                cvadd("SUPPLY","<55",C[ss<55],context_veto)
                cvadd("SUPPLY","55–65",C[(ss>=55)&(ss<65)],context_veto)
                cvadd("SUPPLY","≥65",C[ss>=65],context_veto)
            if "extension" in C.columns:
                ex=pd.to_numeric(C["extension"],errors="coerce")
                cvadd("ENTRY","≤1%",C[ex<=0.01],context_veto)
                cvadd("ENTRY","1–2%",C[(ex>0.01)&(ex<=0.02)],context_veto)
                cvadd("ENTRY",">2%",C[ex>0.02],context_veto)

            # Combined veto-style conditions
            if "v6_tier" in C.columns and "v6_edge_count" in C.columns:
                ec=pd.to_numeric(C["v6_edge_count"],errors="coerce")
                tb=C["v6_tier"].astype(str)=="B"
                cvadd("COMBO","Tier B",C[tb],context_veto)
                cvadd("COMBO","Tier B + Edge=6",C[tb&(ec==6)],context_veto)

                if "supply_score" in C.columns:
                    ss=pd.to_numeric(C["supply_score"],errors="coerce")
                    cvadd("COMBO","B + Edge=6 + Supply<55",C[tb&(ec==6)&(ss<55)],context_veto)
                    cvadd("COMBO","B + Edge=6 + Supply≥55",C[tb&(ec==6)&(ss>=55)],context_veto)
                if "extension" in C.columns:
                    ex=pd.to_numeric(C["extension"],errors="coerce")
                    cvadd("COMBO","B + Edge=6 + Ext>1%",C[tb&(ec==6)&(ex>0.01)],context_veto)
                    cvadd("COMBO","B + Edge=6 + Ext≤1%",C[tb&(ec==6)&(ex<=0.01)],context_veto)
                if "supply_score" in C.columns and "extension" in C.columns:
                    ss=pd.to_numeric(C["supply_score"],errors="coerce")
                    ex=pd.to_numeric(C["extension"],errors="coerce")
                    cvadd("COMBO","B+E6 + weak supply OR ext>1%",
                          C[tb&(ec==6)&((ss<55)|(ex>0.01))],context_veto)
                    cvadd("COMBO","B+E6 + Supply≥55 + Ext≤1%",
                          C[tb&(ec==6)&(ss>=55)&(ex<=0.01)],context_veto)

            # Same diagnostics on recent era only.
            if "date" in C.columns:
                C["date"]=pd.to_datetime(C["date"],errors="coerce")
                R=C[C["date"]>=pd.Timestamp("2022-01-01")].copy()
                if len(R):
                    if "v6_tier" in R.columns:
                        for nm in ["A1","A2","B","WATCH","REJECT"]:
                            cvadd("RECENT_TIER",nm,R[R["v6_tier"].astype(str)==nm],context_veto_recent)
                    if "v6_edge_count" in R.columns:
                        ec=pd.to_numeric(R["v6_edge_count"],errors="coerce")
                        for nm,val in [("6",6),("7",7),("8+",8)]:
                            if nm=="8+":
                                g=R[ec>=8]
                            else:
                                g=R[ec==val]
                            cvadd("RECENT_EDGE",nm,g,context_veto_recent)
                    if "supply_score" in R.columns:
                        ss=pd.to_numeric(R["supply_score"],errors="coerce")
                        cvadd("RECENT_SUPPLY","<55",R[ss<55],context_veto_recent)
                        cvadd("RECENT_SUPPLY","≥55",R[ss>=55],context_veto_recent)
                    if "extension" in R.columns:
                        ex=pd.to_numeric(R["extension"],errors="coerce")
                        cvadd("RECENT_ENTRY","≤1%",R[ex<=0.01],context_veto_recent)
                        cvadd("RECENT_ENTRY",">1%",R[ex>0.01],context_veto_recent)

    veto_validation=[]

    def _vv_add(scope,label,g):
        if len(g):
            veto_validation.append({"scope":scope,"name":label,**_v6_shadow_metrics(g)})

    # V6.4 candidate veto validation: compare BEFORE vs AFTER, no rerun.
    # Candidates:
    # A: Extension >2% veto
    # B: Supply >=65 veto
    # C: Combined A OR B veto
    if len(T):
        scopes=[("ALL_466",T)]
        if "ticker" in T.columns:
            tick=T["ticker"].astype(str)
            scopes.append(("ORIGINAL_122",T[tick.isin(set(V5_ORIGINAL_122))]))
            scopes.append(("VALIDATION_324",T[tick.isin(set(V5_VALIDATION))]))

        if "date" in T.columns:
            Td=T.copy()
            Td["date"]=pd.to_datetime(Td["date"],errors="coerce")
            scopes.append(("2007–2021",Td[Td["date"]<pd.Timestamp("2022-01-01")]))
            scopes.append(("2022–2026",Td[Td["date"]>=pd.Timestamp("2022-01-01")]))

        for scope_name,S in scopes:
            if S.empty: continue
            _vv_add(scope_name,"BEFORE",S)

            ex=pd.to_numeric(S["extension"],errors="coerce") if "extension" in S.columns else pd.Series(index=S.index,dtype=float)
            ss=pd.to_numeric(S["supply_score"],errors="coerce") if "supply_score" in S.columns else pd.Series(index=S.index,dtype=float)

            if "extension" in S.columns:
                _vv_add(scope_name,"AFTER veto Ext>2%",S[~(ex>0.02)])
            if "supply_score" in S.columns:
                _vv_add(scope_name,"AFTER veto Supply≥65",S[~(ss>=65)])
            if "extension" in S.columns and "supply_score" in S.columns:
                keep=~((ex>0.02)|(ss>=65))
                _vv_add(scope_name,"AFTER combined veto",S[keep])

    ranking_diag=[]
    opportunity_diag=[]

    def _rk_add(group,label,g):
        if len(g):
            ranking_diag.append({"group":group,"name":label,**_v6_shadow_metrics(g)})

    def _op_add(group,label,g):
        if len(g):
            opportunity_diag.append({"group":group,"name":label,**_v6_shadow_metrics(g)})

    # V6.5 Ranking Diagnostic — no rerun, existing V6.3 trades only.
    if len(T):
        # Rank buckets overall
        if "v6_rank" in T.columns:
            rk=pd.to_numeric(T["v6_rank"],errors="coerce")
            _rk_add("ALL","Rank 1",T[rk==1])
            _rk_add("ALL","Rank 2",T[rk==2])
            _rk_add("ALL","Rank 3",T[rk==3])
            _rk_add("ALL","Rank 4+",T[rk>=4])

        # Same by market character
        if "v6_market_character" in T.columns and "v6_rank" in T.columns:
            rk=pd.to_numeric(T["v6_rank"],errors="coerce")
            for mc in ["POWER_TREND","BULL_TREND"]:
                M=T[T["v6_market_character"].astype(str)==mc]
                if len(M):
                    mr=pd.to_numeric(M["v6_rank"],errors="coerce")
                    _rk_add(mc,"Rank 1",M[mr==1])
                    _rk_add(mc,"Rank 2",M[mr==2])
                    _rk_add(mc,"Rank 3",M[mr==3])
                    _rk_add(mc,"Rank 4+",M[mr>=4])

        # Validation cohort ranking
        if "ticker" in T.columns and "v6_rank" in T.columns:
            tick=T["ticker"].astype(str)
            V=T[tick.isin(set(V5_VALIDATION))]
            vr=pd.to_numeric(V["v6_rank"],errors="coerce")
            _rk_add("VALIDATION_324","Rank 1",V[vr==1])
            _rk_add("VALIDATION_324","Rank 2",V[vr==2])
            _rk_add("VALIDATION_324","Rank 3",V[vr==3])
            _rk_add("VALIDATION_324","Rank 4+",V[vr>=4])

        # Recent ranking
        if "date" in T.columns and "v6_rank" in T.columns:
            Td=T.copy()
            Td["date"]=pd.to_datetime(Td["date"],errors="coerce")
            R=Td[Td["date"]>=pd.Timestamp("2022-01-01")]
            rr=pd.to_numeric(R["v6_rank"],errors="coerce")
            _rk_add("2022–2026","Rank 1",R[rr==1])
            _rk_add("2022–2026","Rank 2",R[rr==2])
            _rk_add("2022–2026","Rank 3",R[rr==3])
            _rk_add("2022–2026","Rank 4+",R[rr>=4])

        # Opportunity-quality comparison: not hard gates, descriptive stacks.
        cols=set(T.columns)
        if "v6_market_character" in cols:
            P=T[T["v6_market_character"].astype(str)=="POWER_TREND"].copy()
            _op_add("POWER","ALL",P)
            if "v6_edge_count" in cols:
                ec=pd.to_numeric(P["v6_edge_count"],errors="coerce")
                _op_add("POWER","Edge≥7",P[ec>=7])
                _op_add("POWER","Edge≥8",P[ec>=8])
            if "v6_red_count" in cols:
                rc=pd.to_numeric(P["v6_red_count"],errors="coerce")
                _op_add("POWER","Red=0",P[rc==0])
                _op_add("POWER","Red≤1",P[rc<=1])
            if "extension" in cols:
                ex=pd.to_numeric(P["extension"],errors="coerce")
                _op_add("POWER","Extension≤1%",P[ex<=0.01])
            if "volratio" in cols:
                vv=pd.to_numeric(P["volratio"],errors="coerce")
                _op_add("POWER","Volume≥1.8x",P[vv>=1.8])
            if "rs" in cols:
                rr=pd.to_numeric(P["rs"],errors="coerce")
                _op_add("POWER","RS2≥90",P[rr>=90])

            if all(c in cols for c in ["v6_edge_count","v6_red_count","extension"]):
                ec=pd.to_numeric(P["v6_edge_count"],errors="coerce")
                rc=pd.to_numeric(P["v6_red_count"],errors="coerce")
                ex=pd.to_numeric(P["extension"],errors="coerce")
                _op_add("POWER","Edge≥7 + Red=0 + Ext≤1%",P[(ec>=7)&(rc==0)&(ex<=0.01)])

    ranking_replay=[]

    def _rr_add(scope,label,g):
        if len(g):
            ranking_replay.append({"scope":scope,"name":label,**_v6_shadow_metrics(g)})

    # V6.5.1: ranking replay only. No rerun and no new trade generation.
    # Goal: test ranking as a preference mechanism, NOT as a hard gate.
    # Candidate order is intentionally simple and theory-led:
    #   1) POWER_TREND context
    #   2) better entry location (Extension <=1% first, then lower extension)
    #   3) demand confirmation (Volume >=1.8x first, then higher volume)
    #   4) RS2 only as late tie-breaker
    if len(T) and "date" in T.columns:
        R=T.copy()
        R["date"]=pd.to_datetime(R["date"],errors="coerce")

        mc_power=(R["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in R.columns else pd.Series(False,index=R.index)
        ext=pd.to_numeric(R["extension"],errors="coerce") if "extension" in R.columns else pd.Series(999.0,index=R.index)
        vol=pd.to_numeric(R["volratio"],errors="coerce") if "volratio" in R.columns else pd.Series(0.0,index=R.index)
        rs2=pd.to_numeric(R["rs"],errors="coerce") if "rs" in R.columns else pd.Series(0.0,index=R.index)

        R["_power"]=mc_power.astype(int)
        R["_goodloc"]=(ext<=0.01).astype(int)
        R["_goodvol"]=(vol>=1.8).astype(int)
        R["_ext"]=ext.fillna(999.0)
        R["_vol"]=vol.fillna(0.0)
        R["_rs2"]=rs2.fillna(0.0)

        # Rank within each signal date. Desc for context/flags/volume/RS2; asc for extension.
        R=R.sort_values(
            ["date","_power","_goodloc","_goodvol","_ext","_vol","_rs2"],
            ascending=[True,False,False,False,True,False,False]
        )
        R["v651_rank"]=R.groupby("date").cumcount()+1

        scopes=[("ALL",R)]
        if "ticker" in R.columns:
            tick=R["ticker"].astype(str)
            scopes.append(("VALIDATION_324",R[tick.isin(set(V5_VALIDATION))]))
        scopes.append(("2022–2026",R[R["date"]>=pd.Timestamp("2022-01-01")]))
        if "v6_market_character" in R.columns:
            scopes.append(("POWER_TREND",R[R["v6_market_character"].astype(str)=="POWER_TREND"]))

        for scope_name,S in scopes:
            if S.empty: continue
            rrk=pd.to_numeric(S["v651_rank"],errors="coerce")
            _rr_add(scope_name,"NEW Rank 1",S[rrk==1])
            _rr_add(scope_name,"NEW Rank 1–2",S[rrk<=2])
            _rr_add(scope_name,"NEW Rank 1–3",S[rrk<=3])

            if "v6_rank" in S.columns:
                old=pd.to_numeric(S["v6_rank"],errors="coerce")
                _rr_add(scope_name,"OLD Rank 1",S[old==1])

    rank12_diag=[]
    rank12_features=[]

    def _r12_add(scope,label,g):
        if len(g):
            rank12_diag.append({"scope":scope,"name":label,**_v6_shadow_metrics(g)})

    # V6.5.2: diagnose why NEW Rank 2 often beats NEW Rank 1.
    if len(T) and "date" in T.columns:
        R=T.copy()
        R["date"]=pd.to_datetime(R["date"],errors="coerce")

        mc_power=(R["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in R.columns else pd.Series(False,index=R.index)
        ext=pd.to_numeric(R["extension"],errors="coerce") if "extension" in R.columns else pd.Series(999.0,index=R.index)
        vol=pd.to_numeric(R["volratio"],errors="coerce") if "volratio" in R.columns else pd.Series(0.0,index=R.index)
        rs2=pd.to_numeric(R["rs"],errors="coerce") if "rs" in R.columns else pd.Series(0.0,index=R.index)

        R["_power"]=mc_power.astype(int)
        R["_goodloc"]=(ext<=0.01).astype(int)
        R["_goodvol"]=(vol>=1.8).astype(int)
        R["_ext"]=ext.fillna(999.0)
        R["_vol"]=vol.fillna(0.0)
        R["_rs2"]=rs2.fillna(0.0)

        R=R.sort_values(
            ["date","_power","_goodloc","_goodvol","_ext","_vol","_rs2"],
            ascending=[True,False,False,False,True,False,False]
        )
        R["v651_rank"]=R.groupby("date").cumcount()+1

        scopes=[("ALL",R)]
        if "ticker" in R.columns:
            tick=R["ticker"].astype(str)
            scopes.append(("VALIDATION_324",R[tick.isin(set(V5_VALIDATION))]))
        scopes.append(("2022–2026",R[R["date"]>=pd.Timestamp("2022-01-01")]))
        if "v6_market_character" in R.columns:
            scopes.append(("POWER_TREND",R[R["v6_market_character"].astype(str)=="POWER_TREND"]))

        for scope_name,S in scopes:
            if S.empty: continue
            rr=pd.to_numeric(S["v651_rank"],errors="coerce")
            _r12_add(scope_name,"NEW Rank 1",S[rr==1])
            _r12_add(scope_name,"NEW Rank 2",S[rr==2])
            _r12_add(scope_name,"NEW Rank 3",S[rr==3])

        # Head-to-head only on dates that have both Rank1 and Rank2.
        r1=R[R["v651_rank"]==1].copy()
        r2=R[R["v651_rank"]==2].copy()
        if len(r1) and len(r2):
            date12=set(r1["date"].dropna()) & set(r2["date"].dropna())
            H=R[R["date"].isin(date12)]
            _r12_add("HEAD_TO_HEAD","Rank 1 on same dates",H[H["v651_rank"]==1])
            _r12_add("HEAD_TO_HEAD","Rank 2 on same dates",H[H["v651_rank"]==2])

        # Feature medians to show systematic differences between Rank1 and Rank2.
        features=["extension","volratio","rs","supply_score","sector_score","leader_score",
                  "group_breadth","v6_edge_count","v6_red_count"]
        for feat in features:
            if feat not in R.columns: continue
            row={"feature":feat}
            for rank_no in [1,2,3]:
                s=pd.to_numeric(R.loc[R["v651_rank"]==rank_no,feat],errors="coerce").dropna()
                row[f"r{rank_no}"]=float(s.median()) if len(s) else None
            rank12_features.append(row)

    pairwise_diag=[]
    pairwise_features=[]

    # V6.5.3 Pairwise head-to-head: on dates where both NEW Rank1 and Rank2 exist,
    # inspect which one actually won and how their features differ.
    if len(T) and "date" in T.columns:
        R=T.copy()
        R["date"]=pd.to_datetime(R["date"],errors="coerce")

        mc_power=(R["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in R.columns else pd.Series(False,index=R.index)
        ext=pd.to_numeric(R["extension"],errors="coerce") if "extension" in R.columns else pd.Series(999.0,index=R.index)
        vol=pd.to_numeric(R["volratio"],errors="coerce") if "volratio" in R.columns else pd.Series(0.0,index=R.index)
        rs2=pd.to_numeric(R["rs"],errors="coerce") if "rs" in R.columns else pd.Series(0.0,index=R.index)

        R["_power"]=mc_power.astype(int)
        R["_goodloc"]=(ext<=0.01).astype(int)
        R["_goodvol"]=(vol>=1.8).astype(int)
        R["_ext"]=ext.fillna(999.0)
        R["_vol"]=vol.fillna(0.0)
        R["_rs2"]=rs2.fillna(0.0)

        R=R.sort_values(
            ["date","_power","_goodloc","_goodvol","_ext","_vol","_rs2"],
            ascending=[True,False,False,False,True,False,False]
        )
        R["v651_rank"]=R.groupby("date").cumcount()+1

        r1=R[R["v651_rank"]==1].copy()
        r2=R[R["v651_rank"]==2].copy()
        pairs=r1.merge(r2,on="date",suffixes=("_r1","_r2"))
        if len(pairs):
            # identify better trade by return_pct when available
            if "return_pct_r1" in pairs.columns and "return_pct_r2" in pairs.columns:
                a=pd.to_numeric(pairs["return_pct_r1"],errors="coerce")
                b=pd.to_numeric(pairs["return_pct_r2"],errors="coerce")
                pairs["winner"]=pd.Series("TIE",index=pairs.index)
                pairs.loc[a>b,"winner"]="R1"
                pairs.loc[b>a,"winner"]="R2"

                def _pair_group(label, P):
                    if len(P):
                        r1m=_v6_shadow_metrics(pd.DataFrame({
                            "return_pct":pd.to_numeric(P["return_pct_r1"],errors="coerce")
                        }))
                        r2m=_v6_shadow_metrics(pd.DataFrame({
                            "return_pct":pd.to_numeric(P["return_pct_r2"],errors="coerce")
                        }))
                        pairwise_diag.append({
                            "scope":label,
                            "pairs":int(len(P)),
                            "r1_better":int((P["winner"]=="R1").sum()),
                            "r2_better":int((P["winner"]=="R2").sum()),
                            "ties":int((P["winner"]=="TIE").sum()),
                            "r1_pf":r1m["pf"],"r1_avg":r1m["avg_return"],"r1_win":r1m["win_rate"],
                            "r2_pf":r2m["pf"],"r2_avg":r2m["avg_return"],"r2_win":r2m["win_rate"],
                        })

                _pair_group("ALL SAME-DATE",pairs)

                if "ticker_r1" in pairs.columns and "ticker_r2" in pairs.columns:
                    vset=set(V5_VALIDATION)
                    PV=pairs[pairs["ticker_r1"].astype(str).isin(vset) & pairs["ticker_r2"].astype(str).isin(vset)]
                    _pair_group("VALIDATION_324",PV)

                PR=pairs[pairs["date"]>=pd.Timestamp("2022-01-01")]
                _pair_group("2022–2026",PR)

                if "v6_market_character_r1" in pairs.columns and "v6_market_character_r2" in pairs.columns:
                    PP=pairs[(pairs["v6_market_character_r1"].astype(str)=="POWER_TREND") &
                             (pairs["v6_market_character_r2"].astype(str)=="POWER_TREND")]
                    _pair_group("POWER_TREND",PP)

                # Feature deltas split by which rank actually did better.
                features=["extension","volratio","rs","supply_score","sector_score","leader_score",
                          "group_breadth","v6_edge_count","v6_red_count"]
                for feat in features:
                    c1=f"{feat}_r1"; c2=f"{feat}_r2"
                    if c1 not in pairs.columns or c2 not in pairs.columns:
                        continue
                    for winner in ["R1","R2"]:
                        P=pairs[pairs["winner"]==winner]
                        if len(P)==0: continue
                        x1=pd.to_numeric(P[c1],errors="coerce")
                        x2=pd.to_numeric(P[c2],errors="coerce")
                        d=(x1-x2).dropna()
                        if len(d):
                            pairwise_features.append({
                                "winner":winner,
                                "feature":feat,
                                "pairs":int(len(d)),
                                "median_r1":float(x1.median()),
                                "median_r2":float(x2.median()),
                                "median_delta_r1_minus_r2":float(d.median())
                            })

    demand_rank_diag=[]

    def _dr_add(scope,label,g):
        if len(g):
            demand_rank_diag.append({"scope":scope,"name":label,**_v6_shadow_metrics(g)})

    # V6.5.4 Demand-First replay.
    # Pairwise evidence suggests entry closeness is over-prioritized:
    # Rank1 is always closer to pivot, whether it wins or loses.
    # Relative demand/volume is more discriminative within the same-date pair.
    if len(T) and "date" in T.columns:
        D=T.copy()
        D["date"]=pd.to_datetime(D["date"],errors="coerce")

        power=(D["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in D.columns else pd.Series(False,index=D.index)
        ext=pd.to_numeric(D["extension"],errors="coerce") if "extension" in D.columns else pd.Series(999.0,index=D.index)
        vol=pd.to_numeric(D["volratio"],errors="coerce") if "volratio" in D.columns else pd.Series(0.0,index=D.index)
        rs2=pd.to_numeric(D["rs"],errors="coerce") if "rs" in D.columns else pd.Series(0.0,index=D.index)

        D["_power"]=power.astype(int)
        D["_goodvol"]=(vol>=1.8).astype(int)
        D["_goodloc"]=(ext<=0.01).astype(int)
        D["_vol"]=vol.fillna(0.0)
        D["_ext"]=ext.fillna(999.0)
        D["_rs2"]=rs2.fillna(0.0)

        # Old/current replay rank (location-first)
        O=D.sort_values(
            ["date","_power","_goodloc","_goodvol","_ext","_vol","_rs2"],
            ascending=[True,False,False,False,True,False,False]
        ).copy()
        O["rank_location_first"]=O.groupby("date").cumcount()+1

        # Candidate new rank: demand first, location only after demand confirmation.
        N=D.sort_values(
            ["date","_power","_goodvol","_goodloc","_vol","_ext","_rs2"],
            ascending=[True,False,False,False,False,True,False]
        ).copy()
        N["rank_demand_first"]=N.groupby("date").cumcount()+1

        scopes=[("ALL",None)]
        if "ticker" in D.columns:
            scopes.append(("VALIDATION_324","validation"))
        scopes.append(("2022–2026","recent"))
        scopes.append(("POWER_TREND","power"))

        for scope_name,kind in scopes:
            OO=O.copy(); NN=N.copy()
            if kind=="validation" and "ticker" in D.columns:
                vset=set(V5_VALIDATION)
                OO=OO[OO["ticker"].astype(str).isin(vset)]
                NN=NN[NN["ticker"].astype(str).isin(vset)]
            elif kind=="recent":
                OO=OO[OO["date"]>=pd.Timestamp("2022-01-01")]
                NN=NN[NN["date"]>=pd.Timestamp("2022-01-01")]
            elif kind=="power" and "v6_market_character" in D.columns:
                OO=OO[OO["v6_market_character"].astype(str)=="POWER_TREND"]
                NN=NN[NN["v6_market_character"].astype(str)=="POWER_TREND"]

            _dr_add(scope_name,"LOCATION-FIRST Rank1",OO[OO["rank_location_first"]==1])
            _dr_add(scope_name,"DEMAND-FIRST Rank1",NN[NN["rank_demand_first"]==1])
            _dr_add(scope_name,"DEMAND-FIRST Rank1–2",NN[NN["rank_demand_first"]<=2])


    portfolio_rows=[]
    portfolio_years=[]

    def _portfolio_sim(source, top_n=1, max_positions=5, risk_pct=0.003, initial_equity=100000.0, label=""):
        if source is None or source.empty or "date" not in source.columns or "return_pct" not in source.columns:
            return None, []
        D=source.copy()
        D["date"]=pd.to_datetime(D["date"],errors="coerce")
        D=D[D["date"].notna()].copy()

        power=(D["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in D.columns else pd.Series(False,index=D.index)
        ext=pd.to_numeric(D["extension"],errors="coerce") if "extension" in D.columns else pd.Series(999.0,index=D.index)
        vol=pd.to_numeric(D["volratio"],errors="coerce") if "volratio" in D.columns else pd.Series(0.0,index=D.index)
        rs2=pd.to_numeric(D["rs"],errors="coerce") if "rs" in D.columns else pd.Series(0.0,index=D.index)
        D["_power"]=power.astype(int); D["_goodvol"]=(vol>=1.8).astype(int); D["_goodloc"]=(ext<=0.01).astype(int)
        D["_vol"]=vol.fillna(0.0); D["_ext"]=ext.fillna(999.0); D["_rs2"]=rs2.fillna(0.0)
        D=D.sort_values(["date","_power","_goodvol","_goodloc","_vol","_ext","_rs2"],
                        ascending=[True,False,False,False,False,True,False]).copy()
        D["_rank"]=D.groupby("date").cumcount()+1
        D=D[D["_rank"]<=int(top_n)].copy()
        if D.empty:return None,[]

        hold=pd.to_numeric(D["hold_days"],errors="coerce").fillna(20).clip(lower=1).round().astype(int) if "hold_days" in D.columns else pd.Series(20,index=D.index)
        D["_exit_date"]=[d+pd.offsets.BDay(int(h)) for d,h in zip(D["date"],hold)]
        D["_ret"]=pd.to_numeric(D["return_pct"],errors="coerce").fillna(0.0)
        stop=pd.to_numeric(D["stop_pct"],errors="coerce").abs() if "stop_pct" in D.columns else pd.Series(0.07,index=D.index)
        D["_stop"]=stop.where((stop>0.005)&(stop<0.30),0.07)

        equity=cash=float(initial_equity); peak=equity; max_dd=0.0
        open_pos=[]; realized=[]; skipped_capacity=0

        def close_due(day):
            nonlocal equity,cash,peak,max_dd,open_pos
            due=[p for p in open_pos if p["exit_date"]<=day]
            keep=[p for p in open_pos if p["exit_date"]>day]
            for p in due:
                pnl=p["capital"]*p["ret"]; cash+=p["capital"]+pnl
                realized.append({"exit_date":p["exit_date"],"pnl":pnl})
            open_pos=keep
            equity=cash+sum(p["capital"] for p in open_pos)
            peak=max(peak,equity)
            if peak>0:max_dd=min(max_dd,equity/peak-1.0)

        for day,g in D.groupby("date",sort=True):
            close_due(day)
            equity=cash+sum(p["capital"] for p in open_pos)
            for _,r in g.sort_values("_rank").iterrows():
                if len(open_pos)>=int(max_positions):
                    skipped_capacity+=1; continue
                cap=min(equity*float(risk_pct)/float(r["_stop"]), equity*0.25, cash)
                if cap<100: continue
                cash-=cap
                open_pos.append({"exit_date":r["_exit_date"],"capital":float(cap),"ret":float(r["_ret"])})
        for day in sorted({p["exit_date"] for p in open_pos}): close_due(day)
        equity=cash

        first=D["date"].min(); last=max(D["_exit_date"].max(),D["date"].max())
        years=max((last-first).days/365.25,1/365.25)
        cagr=(equity/initial_equity)**(1/years)-1 if equity>0 else -1.0
        pnl=[x["pnl"] for x in realized]; wins=[x for x in pnl if x>0]; losses=[x for x in pnl if x<0]
        pf=sum(wins)/(-sum(losses)) if losses else (999.0 if wins else 0.0)

        yr=[]; running=float(initial_equity)
        if realized:
            RR=pd.DataFrame(realized); RR["year"]=pd.to_datetime(RR["exit_date"]).dt.year
            for y,gy in RR.groupby("year",sort=True):
                start=running; p=float(gy["pnl"].sum()); running+=p
                yr.append({"config":label,"year":int(y),"return":p/start if start else 0.0,"end_equity":running,"trades":int(len(gy))})

        return {
            "name":label,"final_equity":equity,"total_return":equity/initial_equity-1.0,"cagr":cagr,
            "max_drawdown":max_dd,"trades":len(realized),"win_rate":len(wins)/len(realized) if realized else 0.0,
            "pf":pf,"skipped_capacity":skipped_capacity
        },yr

    if len(T):
        for label,tn,mp,risk in [
            ("Top1 · 5仓 · Risk0.3%",1,5,0.003),
            ("Top1 · 8仓 · Risk0.5%",1,8,0.005),
            ("Top2 · 8仓 · Risk0.3%",2,8,0.003),
            ("Top2 · 10仓 · Risk0.5%",2,10,0.005),
        ]:
            sm,yy=_portfolio_sim(T,tn,mp,risk,label=label)
            if sm: portfolio_rows.append(sm); portfolio_years.extend(yy)
        TT=T.copy(); TT["date"]=pd.to_datetime(TT["date"],errors="coerce")
        REC=TT[TT["date"]>=pd.Timestamp("2022-01-01")].copy()
        for label,tn,mp,risk in [
            ("2022–26 Top1 · 5仓 · 0.3%",1,5,0.003),
            ("2022–26 Top2 · 8仓 · 0.3%",2,8,0.003),
        ]:
            sm,yy=_portfolio_sim(REC,tn,mp,risk,label=label)
            if sm: portfolio_rows.append(sm); portfolio_years.extend(yy)


    portfolio_audit=[]
    portfolio_audit_years=[]

    def _pf_from_returns(vals):
        x=pd.to_numeric(pd.Series(vals),errors="coerce").dropna()
        if x.empty:return 0.0
        gw=float(x[x>0].sum()); gl=float(-x[x<0].sum())
        return gw/gl if gl>0 else (999.0 if gw>0 else 0.0)

    def _audit_sim(source, top_n=1, max_positions=5, risk_pct=0.003, power_only=False,
                   initial_equity=100000.0, label=""):
        if source is None or source.empty or "date" not in source.columns or "return_pct" not in source.columns:
            return None, []

        D=source.copy()
        D["date"]=pd.to_datetime(D["date"],errors="coerce")
        D=D[D["date"].notna()].copy()

        if power_only and "v6_market_character" in D.columns:
            D=D[D["v6_market_character"].astype(str)=="POWER_TREND"].copy()
        if D.empty:return None,[]

        # Frozen V6.5.4 Demand-First ordering.
        power=(D["v6_market_character"].astype(str)=="POWER_TREND") if "v6_market_character" in D.columns else pd.Series(False,index=D.index)
        ext=pd.to_numeric(D["extension"],errors="coerce") if "extension" in D.columns else pd.Series(999.0,index=D.index)
        vol=pd.to_numeric(D["volratio"],errors="coerce") if "volratio" in D.columns else pd.Series(0.0,index=D.index)
        rs2=pd.to_numeric(D["rs"],errors="coerce") if "rs" in D.columns else pd.Series(0.0,index=D.index)
        D["_power"]=power.astype(int)
        D["_goodvol"]=(vol>=1.8).astype(int)
        D["_goodloc"]=(ext<=0.01).astype(int)
        D["_vol"]=vol.fillna(0.0)
        D["_ext"]=ext.fillna(999.0)
        D["_rs2"]=rs2.fillna(0.0)

        D=D.sort_values(
            ["date","_power","_goodvol","_goodloc","_vol","_ext","_rs2"],
            ascending=[True,False,False,False,False,True,False]
        ).copy()
        D["_rank"]=D.groupby("date").cumcount()+1
        D=D[D["_rank"]<=int(top_n)].copy()
        if D.empty:return None,[]

        hold=pd.to_numeric(D["hold_days"],errors="coerce").fillna(20).clip(lower=1).round().astype(int) if "hold_days" in D.columns else pd.Series(20,index=D.index)
        D["_hold"]=hold
        D["_exit_date"]=[d+pd.offsets.BDay(int(h)) for d,h in zip(D["date"],hold)]
        D["_ret"]=pd.to_numeric(D["return_pct"],errors="coerce").fillna(0.0)

        stop=pd.to_numeric(D["stop_pct"],errors="coerce").abs() if "stop_pct" in D.columns else pd.Series(0.07,index=D.index)
        D["_stop"]=stop.where((stop>0.005)&(stop<0.30),0.07)

        equity=cash=float(initial_equity)
        peak=equity
        max_dd=0.0
        open_pos=[]
        realized=[]
        executed=[]
        skipped=[]
        snapshots=[]

        def mark_snapshot(day):
            eq=cash+sum(p["capital"] for p in open_pos)
            invested=sum(p["capital"] for p in open_pos)
            snapshots.append({
                "date":day,
                "open":len(open_pos),
                "invested_pct":invested/eq if eq>0 else 0.0
            })

        def close_due(day):
            nonlocal equity,cash,peak,max_dd,open_pos
            due=[p for p in open_pos if p["exit_date"]<=day]
            keep=[p for p in open_pos if p["exit_date"]>day]
            for p in due:
                pnl=p["capital"]*p["ret"]
                cash+=p["capital"]+pnl
                realized.append({
                    "entry_date":p["entry_date"],"exit_date":p["exit_date"],
                    "pnl":pnl,"ret":p["ret"],"capital":p["capital"]
                })
            open_pos=keep
            equity=cash+sum(p["capital"] for p in open_pos)
            peak=max(peak,equity)
            if peak>0:max_dd=min(max_dd,equity/peak-1.0)

        for day,g in D.groupby("date",sort=True):
            close_due(day)
            equity=cash+sum(p["capital"] for p in open_pos)

            for _,r in g.sort_values("_rank").iterrows():
                record={
                    "date":day,"ret":float(r["_ret"]),"hold":int(r["_hold"]),
                    "stop":float(r["_stop"]),"rank":int(r["_rank"])
                }
                if len(open_pos)>=int(max_positions):
                    record["reason"]="capacity"
                    skipped.append(record)
                    continue

                target_cap=equity*float(risk_pct)/float(r["_stop"])
                target_cap=min(target_cap,equity*0.25)
                cap=min(target_cap,cash)

                if cap<100:
                    record["reason"]="cash"
                    skipped.append(record)
                    continue

                record["capital"]=float(cap)
                record["size_pct"]=float(cap/equity) if equity>0 else 0.0
                executed.append(record)
                cash-=cap
                open_pos.append({
                    "entry_date":day,"exit_date":r["_exit_date"],
                    "capital":float(cap),"ret":float(r["_ret"])
                })
                equity=cash+sum(p["capital"] for p in open_pos)

            mark_snapshot(day)

        for day in sorted({p["exit_date"] for p in open_pos}):
            close_due(day)
            mark_snapshot(day)

        equity=cash

        exe=pd.DataFrame(executed)
        skp=pd.DataFrame(skipped)
        snap=pd.DataFrame(snapshots)
        real=pd.DataFrame(realized)

        first=D["date"].min()
        last=max(D["_exit_date"].max(),D["date"].max())
        years=max((last-first).days/365.25,1/365.25)
        cagr=(equity/initial_equity)**(1/years)-1 if equity>0 else -1.0

        if not real.empty:
            wins=real[real["pnl"]>0]
            losses=real[real["pnl"]<0]
            gw=float(wins["pnl"].sum())
            gl=float(-losses["pnl"].sum())
            pf=gw/gl if gl>0 else (999.0 if gw>0 else 0.0)
            win_rate=float((real["pnl"]>0).mean())
        else:
            pf=0.0; win_rate=0.0

        signal_days=int(D["date"].nunique())
        total_candidates=int(len(D))
        executed_n=int(len(exe))
        skipped_n=int(len(skp))
        cap_skips=int((skp["reason"]=="capacity").sum()) if not skp.empty else 0
        cash_skips=int((skp["reason"]=="cash").sum()) if not skp.empty else 0

        row={
            "name":label,
            "power_only":bool(power_only),
            "top_n":int(top_n),
            "max_positions":int(max_positions),
            "risk_pct":float(risk_pct),
            "final_equity":float(equity),
            "cagr":float(cagr),
            "max_drawdown":float(max_dd),
            "pf":float(pf),
            "win_rate":float(win_rate),
            "signal_days":signal_days,
            "candidates":total_candidates,
            "executed":executed_n,
            "execution_rate":float(executed_n/total_candidates) if total_candidates else 0.0,
            "capacity_skips":cap_skips,
            "cash_skips":cash_skips,
            "avg_position_pct":float(exe["size_pct"].mean()) if not exe.empty else 0.0,
            "median_position_pct":float(exe["size_pct"].median()) if not exe.empty else 0.0,
            "avg_open_positions":float(snap["open"].mean()) if not snap.empty else 0.0,
            "max_open_positions":int(snap["open"].max()) if not snap.empty else 0,
            "avg_invested_pct":float(snap["invested_pct"].mean()) if not snap.empty else 0.0,
            "median_hold":float(exe["hold"].median()) if not exe.empty else 0.0,
            "avg_exec_return":float(exe["ret"].mean()) if not exe.empty else 0.0,
            "exec_pf_raw":float(_pf_from_returns(exe["ret"])) if not exe.empty else 0.0,
            "avg_skipped_return":float(skp["ret"].mean()) if not skp.empty else 0.0,
            "skipped_pf_raw":float(_pf_from_returns(skp["ret"])) if not skp.empty else 0.0,
            "trades_per_year":float(executed_n/years) if years>0 else 0.0,
        }

        yr=[]
        if not real.empty:
            RR=real.copy()
            RR["year"]=pd.to_datetime(RR["exit_date"]).dt.year
            running=float(initial_equity)
            for y,gy in RR.groupby("year",sort=True):
                start=running
                pnl=float(gy["pnl"].sum())
                running+=pnl
                yr.append({
                    "config":label,"year":int(y),
                    "return":pnl/start if start else 0.0,
                    "pnl":pnl,"trades":int(len(gy))
                })

        return row,yr

