@APP.get("/publisher/health")
def publisher_health():
    return jsonify({
        "ok": True,
        "publisher": "embedded",
        "repo": f"{GITHUB_OWNER}/{GITHUB_REPO}",
        "branch": GITHUB_BRANCH,
        "token_configured": bool(GITHUB_TOKEN),
        "secret_configured": bool(PUBLISH_SECRET),
    })

@APP.post("/publisher/publish")
def publisher_publish():
    if not _publisher_auth_ok(request):
        return jsonify({"ok":False,"error":"unauthorized"}), 401

    body = request.get_json(silent=True) or {}
    target = body.get("target")
    content = body.get("content")
    message = body.get("message")

    if target != "app.py" and not (isinstance(target,str) and target.startswith("jlaw_") and target.endswith(".py")):
        return jsonify({"ok":False,"error":"target must be app.py or jlaw_*.py"}), 400
    if not isinstance(content, str):
        return jsonify({"ok":False,"error":"content must be UTF-8 text"}), 400

    try:
        result = _gh_publish(target, content.encode("utf-8"), message)
        return jsonify({"ok":True, **result})
    except Exception as e:
        return jsonify({"ok":False,"error":str(e)}), 500

@APP.get("/health")
def health():
    # Railway healthcheck must be instant and side-effect free.
    # Do NOT touch Volume/storage, pandas, Tiingo, cache files, or background state here.
    return "OK", 200, {"Content-Type":"text/plain; charset=utf-8"}

def _deferred_app_startup():
    """Start non-essential recovery/scheduler only after the web app can answer /health."""
    try:
        time.sleep(3.0)
        recover_stale_v3_status()
    except Exception:
        traceback.print_exc()
    try:
        threading.Thread(target=scheduler_loop, daemon=True).start()
    except Exception:
        traceback.print_exc()

# Never block Gunicorn/Railway startup on recovery, Volume I/O, scheduler, or cache work.
threading.Thread(target=_deferred_app_startup, daemon=True).start()



# ==================== V6.17 OVERNIGHT FULL HISTORY VALIDATION ====================
# Dedicated batch engine. It does NOT reuse the old all-in-one V6.15B worker loop.
V617O_DIR=DATA_DIR/"v617_overnight_full_validation"
V617O_STATUS=V617O_DIR/"status.json"
V617O_STOP=V617O_DIR/"STOP"
v617o_thread=None
V617O_BATCH_SIZE=max(20,int(os.environ.get("V617_OVERNIGHT_BATCH_SIZE","200")))
V617O_MAX_FAILED_RETRIES=max(1,int(os.environ.get("V617_MAX_FAILED_RETRIES","2")))
# Low-disk V6.17: historical listing caches are stored as gzip CSV.
# Existing .csv files remain readable and are migrated safely on resume.
V617O_DISK_RESERVE_MB=max(256,int(os.environ.get("V617_OVERNIGHT_DISK_RESERVE_MB","768")))
# Tiingo Power tuned downloader: concurrent network I/O while a global launch-gap keeps
# requests below ~9,000/hour by default (0.40s between request starts).
V617O_WORKERS=max(2,min(16,int(os.environ.get("V617_OVERNIGHT_WORKERS","8"))))

def _v617o_price_paths(listing_id):
    lid=str(listing_id)
    return V615B_PRICE_DIR/f"{lid}.csv.gz", V615B_PRICE_DIR/f"{lid}.csv"

def _v617o_existing_price_path(listing_id):
    gz,legacy=_v617o_price_paths(listing_id)
    return gz if gz.exists() else (legacy if legacy.exists() else gz)

def _v617o_write_price(df,listing_id):
    gz,legacy=_v617o_price_paths(listing_id)
    gz.parent.mkdir(parents=True,exist_ok=True)
    tmp=gz.with_name(gz.name+".tmp.gz")
    try:
        df.to_csv(tmp,index=False,compression={"method":"gzip","compresslevel":6,"mtime":0})
        os.replace(str(tmp),str(gz))
        if legacy.exists():
            try: legacy.unlink()
            except Exception: pass
    finally:
        try:
            if tmp.exists(): tmp.unlink()
        except Exception: pass
    return gz

def _v617o_migrate_legacy_prices(limit=None):
    """Compress old listing CSVs one at a time; never holds more than one file in memory."""
    moved=0; saved=0
    try:
        files=list(V615B_PRICE_DIR.glob("*.csv"))
    except Exception:
        files=[]
    if limit is not None: files=files[:int(limit)]
    for legacy in files:
        gz=legacy.with_suffix(legacy.suffix+".gz")
        if gz.exists():
            try:
                saved+=max(0,legacy.stat().st_size);legacy.unlink();moved+=1
            except Exception: pass
            continue
        tmp=gz.with_name(gz.name+".tmp.gz")
        try:
            import gzip
            before=legacy.stat().st_size
            with open(legacy,"rb") as src, gzip.open(tmp,"wb",compresslevel=6,mtime=0) as dst:
                shutil.copyfileobj(src,dst,length=1024*1024)
            os.replace(str(tmp),str(gz))
            after=gz.stat().st_size
            legacy.unlink()
            moved+=1;saved+=max(0,before-after)
        except TypeError:
            # Python builds where gzip.open has no mtime argument.
            try:
                import gzip
                with open(legacy,"rb") as src, gzip.open(tmp,"wb",compresslevel=6) as dst:
                    shutil.copyfileobj(src,dst,length=1024*1024)
                before=legacy.stat().st_size;os.replace(str(tmp),str(gz));after=gz.stat().st_size;legacy.unlink();moved+=1;saved+=max(0,before-after)
            except Exception: pass
        except Exception:
            pass
        finally:
            try:
                if tmp.exists(): tmp.unlink()
            except Exception: pass
    return moved,saved

def _v617o_status():
    d={"status":"idle","message":"尚未启动","phase":"","batch":0,"completed":0,"total":0,
       "pending":0,"failed":0,"coverage":0.0,"ended_coverage":0.0,"current":"","error":None}
    if V617O_STATUS.exists():
        try:d.update(json.loads(V617O_STATUS.read_text(encoding="utf-8")))
        except Exception:pass
    return d

def _v617o_write(**kw):
    V617O_DIR.mkdir(parents=True,exist_ok=True)
    d=_v617o_status(); d.update(kw)
    V617O_STATUS.write_text(json.dumps(d,ensure_ascii=False,indent=2,default=str),encoding="utf-8")
    return d

def _v617o_alive():
    return v617o_thread is not None and v617o_thread.is_alive()

def _v617o_manifest_metrics(M):
    if M is None or M.empty:
        return dict(total=0,completed=0,pending=0,failed=0,coverage=0.0,ended_coverage=0.0)
    ix=M.index
    ver=M["verified"].astype(str).str.lower().isin(["true","1","yes"]) if "verified" in M else pd.Series(False,index=ix)
    st=M["status"].astype(str).str.upper() if "status" in M else pd.Series("PENDING",index=ix)
    ended=M["ended"].astype(str).str.lower().isin(["true","1","yes"]) if "ended" in M else pd.Series(False,index=ix)
    pending=(~ver)&(~st.eq("FAILED"))
    failed=(~ver)&st.eq("FAILED")
    return dict(
        total=int(len(M)),
        completed=int(ver.sum()),
        pending=int(pending.sum()),
        failed=int(failed.sum()),
        coverage=float(ver.mean()) if len(M) else 0.0,
        ended_coverage=float(ver[ended].mean()) if ended.any() else 0.0
    )

def _v617o_prepare_manifest():
    M=_v615b_read_manifest()
    if M is not None and not M.empty and len(M)>=1000:
        return M
    candidates=[]
    for root in [V615B_DIR,DATA_DIR]:
        if not root.exists():continue
        for p in root.glob("manifest*.csv"):
            try:
                n=sum(1 for _ in open(p,encoding="utf-8",errors="ignore"))-1
                if n>=1000:candidates.append((n,p))
            except Exception:pass
    if candidates:
        candidates.sort(reverse=True,key=lambda z:z[0])
        M=pd.read_csv(candidates[0][1])
        M.to_csv(V615B_MANIFEST,index=False)
        return M
    _v617o_write(status="starting",message="建立完整历史股票 manifest",phase="manifest")
    _,M=_v615b_prepare_universe(force=True)
    if M is None or M.empty:raise RuntimeError("完整历史 manifest 建立失败")
    return M

def _v617o_reconcile_files(M):
    changed=0
    for i,row in M.iterrows():
        if str(row.get("verified","")).lower() in ("true","1","yes"):continue
        path=_v617o_existing_price_path(row.listing_id)
        if not path.exists():continue
        try:ok,b,cs,ce,err=_v615b_verify_file(path,row.startDate,row.endDate)
        except Exception:ok=False
        if ok:
            M.at[i,"status"]="DONE";M.at[i,"verified"]=True;M.at[i,"bars"]=int(b)
            M.at[i,"cache_start"]=str(pd.Timestamp(cs).date());M.at[i,"cache_end"]=str(pd.Timestamp(ce).date())
            M.at[i,"source"]="existing_v615b_file";M.at[i,"error"]="";changed+=1
    if changed:_v615b_atomic_manifest(M)
    return M

def _v617o_download_listing(idx,row):
    """Worker-safe listing download. It never mutates the shared manifest DataFrame."""
    t=str(row.ticker);lid=str(row.listing_id)
    try:
        x=_v615b_try_reuse_local(t,row.startDate,row.endDate)
        source="local_market_cache" if x is not None else ""
        if x is None:
            x=_v615b_tiingo_listing(t,row.startDate,row.endDate);source="tiingo"
        path=_v617o_write_price(x,lid)
        ok,b,cs,ce,err=_v615b_verify_file(path,row.startDate,row.endDate)
        if not ok:raise RuntimeError(f"verify failed: {err}")
        return idx,"DONE",dict(bars=int(b),cache_start=str(pd.Timestamp(cs).date()),
            cache_end=str(pd.Timestamp(ce).date()),source=source,error="")
    except TiingoRateLimitPause as ex:
        return idx,"RATE_LIMIT",dict(error=str(ex))
    except Exception as ex:
        return idx,"FAILED",dict(error=f"{type(ex).__name__}: {ex}")

def _v617o_apply_result(M,result):
    idx,state,info=result
    if state=="DONE":
        M.at[idx,"status"]="DONE";M.at[idx,"verified"]=True
        for k,v in info.items(): M.at[idx,k]=v
    elif state=="RATE_LIMIT":
        M.at[idx,"status"]="PENDING";M.at[idx,"error"]=info.get("error","")
    else:
        M.at[idx,"status"]="FAILED";M.at[idx,"verified"]=False;M.at[idx,"error"]=info.get("error","")
    return state

def _v617o_sort_work(P):
    """Stable/defensive ordering: older manifests may lack one or more sort columns."""
    cols=[c for c in ["ended","startDate","ticker"] if c in P.columns]
    if not cols:
        return P
    asc=[False if c=="ended" else True for c in cols]
    try:
        return P.sort_values(cols,ascending=asc,na_position="last")
    except Exception:
        return P

def _v617o_disk_free_mb():
    import shutil
    target=DATA_DIR if DATA_DIR.exists() else Path(".")
    return shutil.disk_usage(str(target)).free/(1024*1024)

def _v617o_cleanup_disk():
    # Safe cleanup only. Keep manifest and all completed price caches.
    removed=0; seen=set()
    for root in [DATA_DIR,V615B_DIR,V617O_DIR]:
        try:
            if not root.exists(): continue
            for pat in ("*.tmp","*.tmp.gz","*.part","*.download"):
                for fp in root.rglob(pat):
                    if str(fp) in seen: continue
                    seen.add(str(fp))
                    try: fp.unlink(); removed+=1
                    except Exception: pass
        except Exception: pass
    return removed

def _v617o_engine():
    global v617o_thread
    batch_no=0
    try:
        for p in [V617O_STOP,V615B_STOP]:
            try:
                if p.exists():p.unlink()
            except Exception:pass
        removed=_v617o_cleanup_disk()
        migrated,saved_bytes=_v617o_migrate_legacy_prices()
        free_mb=_v617o_disk_free_mb()
        if free_mb < V617O_DISK_RESERVE_MB:
            _v617o_write(status="disk_low",message=f"低磁盘保护：剩 {free_mb:.0f} MB，保留线 {V617O_DISK_RESERVE_MB} MB；已压缩 {migrated} 个旧历史文件并释放约 {saved_bytes/1024/1024:.1f} MB。不会继续写满磁盘。",phase="disk_preflight",error=None)
            return
        M=_v617o_prepare_manifest()
        M=_v617o_reconcile_files(M)

        # Fair failed-retry bookkeeping. Older manifests do not have this column.
        if "retry_count" not in M.columns:
            M["retry_count"]=0
        M["retry_count"]=pd.to_numeric(M["retry_count"],errors="coerce").fillna(0).astype(int)
        _v615b_atomic_manifest(M)

        while True:
            if V617O_STOP.exists():
                _v615b_atomic_manifest(M)
                _v617o_write(status="paused",message="已安全暂停；缓存与进度已保存")
                return

            met=_v617o_manifest_metrics(M)
            _v617o_write(status="running",message="准备下一批",phase="pending",**met)

            if met["coverage"]>=0.95 and met["ended_coverage"]>=0.90:
                try:_v615b_snapshot_coverage(M)
                except Exception:pass
                _v617o_write(status="coverage_ready",message="历史覆盖达到最终门槛，可以进入冻结大样本 OOS / Daily-MTM",**met)
                return

            st=M["status"].astype(str).str.upper()
            ver=M["verified"].astype(str).str.lower().isin(["true","1","yes"])

            # Phase A: process EVERY unverified row that is not explicitly FAILED.
            # Older manifests use statuses such as NEW / TODO / QUEUED / SKIP / blank,
            # so treating only literal PENDING as work can incorrectly report pending=0.
            work=(~ver)&(~st.eq("FAILED"))
            P=M[work].copy()
            if not P.empty:
                P=_v617o_sort_work(P).head(V617O_BATCH_SIZE)
                # Normalize the selected batch only; preserve completed cache and manifest rows.
                M.loc[P.index,"status"]="PENDING"
                _v615b_atomic_manifest(M)
                phase="unverified"
            else:
                # Phase B: fair retry of FAILED listings.
                # IMPORTANT: never keep taking the same first 200 failures forever.
                failed_mask=(~ver)&st.eq("FAILED")
                retryable=failed_mask & (M["retry_count"] < V617O_MAX_FAILED_RETRIES)

                P=M[retryable].copy()
                if P.empty:
                    exhausted=int(failed_mask.sum())
                    if exhausted:
                        _v617o_write(
                            status="retry_complete",
                            message=f"失败项重试已完成：仍有 {exhausted} 个在 {V617O_MAX_FAILED_RETRIES} 轮重试后无法验证；停止死循环，等待失败原因分类。",
                            phase="retry_complete",
                            final_failed=exhausted,
                            max_failed_retries=V617O_MAX_FAILED_RETRIES,
                            **met
                        )
                        return
                    _v617o_write(status="needs_review",message="没有未验证项目，但覆盖仍未达门槛；检查 manifest 一致性",**met)
                    return

                # Fair ordering: always process the listings with FEWEST retries first.
                # Therefore all failed names get retry #1 before any name gets retry #2.
                min_retry=int(P["retry_count"].min())
                P=P[P["retry_count"].eq(min_retry)].copy()
                P=_v617o_sort_work(P).head(V617O_BATCH_SIZE)

                # Increment BEFORE execution; if Railway restarts mid-batch, these names
                # will not monopolize the front of the queue forever.
                M.loc[P.index,"retry_count"]=M.loc[P.index,"retry_count"].astype(int)+1
                M.loc[P.index,"status"]="PENDING"
                _v615b_atomic_manifest(M)
                phase=f"retry_failed_r{min_retry+1}"

            batch_no+=1
            _v617o_write(status="running",message=f"第 {batch_no} 批：{phase} · {len(P)} listings",
                         phase=phase,batch=batch_no,**_v617o_manifest_metrics(M))

            hit_rate_limit=False
            # Power-mode concurrent downloader. Network work happens in workers; only this
            # coordinator mutates/saves the shared manifest, avoiding CSV corruption.
            from concurrent.futures import ThreadPoolExecutor, wait, FIRST_COMPLETED
            items=list(P.iterrows())
            submitted=0;finished=0;active={}
            with ThreadPoolExecutor(max_workers=V617O_WORKERS,thread_name_prefix="v617dl") as pool:
                while finished < len(items):
                    if V617O_STOP.exists():
                        for f in active: f.cancel()
                        _v615b_atomic_manifest(M)
                        _v617o_write(status="paused",message="已安全暂停；并发下载进度已保存",batch=batch_no)
                        return
                    free_mb=_v617o_disk_free_mb()
                    if free_mb < V617O_DISK_RESERVE_MB:
                        for f in active: f.cancel()
                        _v615b_atomic_manifest(M)
                        _v617o_write(status="disk_low",message=f"低磁盘保护：剩 {free_mb:.0f} MB，已安全保存进度并暂停；不会写满 Volume。",phase="disk_guard",**_v617o_manifest_metrics(M))
                        return
                    while submitted < len(items) and len(active) < V617O_WORKERS and not hit_rate_limit:
                        idx,row=items[submitted]
                        fut=pool.submit(_v617o_download_listing,idx,row)
                        active[fut]=(idx,row);submitted+=1
                    if not active: break
                    done,_=wait(list(active),return_when=FIRST_COMPLETED)
                    for fut in done:
                        idx,row=active.pop(fut);finished+=1
                        try: state=_v617o_apply_result(M,fut.result())
                        except Exception as ex:
                            M.at[idx,"status"]="FAILED";M.at[idx,"verified"]=False;M.at[idx,"error"]=f"worker: {ex}";state="FAILED"
                        if state=="RATE_LIMIT": hit_rate_limit=True
                        if finished%10==0 or finished==len(items) or state=="RATE_LIMIT": _v615b_atomic_manifest(M)
                        _v617o_write(status="running",message=f"第 {batch_no} 批 {finished}/{len(P)} · {V617O_WORKERS}并发",
                            phase=phase,batch=batch_no,current=f"{row.ticker} · {row.listing_id}",workers=V617O_WORKERS,
                            request_gap_sec=V615B_REQUEST_GAP,**_v617o_manifest_metrics(M))
                    if hit_rate_limit:
                        # Do not submit more work. Let already-running requests finish cleanly.
                        for fut,(idx,row) in list(active.items()):
                            try: _v617o_apply_result(M,fut.result())
                            except Exception as ex:
                                M.at[idx,"status"]="FAILED";M.at[idx,"verified"]=False;M.at[idx,"error"]=f"worker: {ex}"
                        active.clear();_v615b_atomic_manifest(M);break

            _v615b_atomic_manifest(M)
            if hit_rate_limit:
                met=_v617o_manifest_metrics(M)
                _v617o_write(status="cooldown",message="Tiingo 429：并发已停止并保存；65分钟后自动继续",phase=phase,batch=batch_no,**met)
                for _ in range(65):
                    if V617O_STOP.exists():return
                    time.sleep(60)
                continue
            # Normal batch completion => immediately advance to next untouched batch.
            continue

    except Exception as ex:
        traceback.print_exc()
        _v617o_write(status="error",message="整晚批次引擎失败",phase="engine_exception",
                     error=f"{type(ex).__name__}: {ex}")
    finally:
        v617o_thread=None

def _v617o_start():
    global v617o_thread
    if _v617o_alive():return False
    # Recompute counters from the existing manifest BEFORE launching the worker.
    # This prevents stale error/pending=0 values from the previous run being shown.
    met={}
    try:
        M0=_v615b_read_manifest()
        if M0 is not None and not M0.empty:
            met=_v617o_manifest_metrics(M0)
    except Exception:
        met={}
    _v617o_write(status="starting",message="已重新计算真实待处理队列；从现有 manifest/cache 断点继续",
                 phase="startup_recount",batch=0,current="",error=None,**met)
    v617o_thread=threading.Thread(target=_v617o_engine,daemon=True)
    v617o_thread.start()
    return True

