V636_DIR=DATA_DIR/'v636_source_faithful_trigger_ab'
V636_STATUS=V636_DIR/'status.json'; V636_RESULT=V636_DIR/'result.json'; V636_STOP=V636_DIR/'STOP'
V636_META_CACHE=V636_DIR/'source_trigger_trades.csv.gz'
