# ========================= V6.55 FIXED: Market Permission / Exposure Semantics =========================
V655_DIR=DATA_DIR/'v655_market_permission_exposure_semantics'
V655_STATUS=V655_DIR/'status.json'; V655_RESULT=V655_DIR/'result.json'
v655_thread=None

def _v655_status():
    x={'status':'idle','message':'尚未运行','elapsed_sec':0,'error':None}
    if V655_STATUS.exists():
        try:x.update(json.loads(V655_STATUS.read_text(encoding='utf-8')))
        except Exception:pass
    return x

def _v655_write(**kw):
    V655_DIR.mkdir(parents=True,exist_ok=True);x=_v655_status();x.update(kw)
    V655_STATUS.write_text(json.dumps(x,ensure_ascii=False,indent=2,default=str),encoding='utf-8');return x

def _v655_alive(): return v655_thread is not None and v655_thread.is_alive()

def _v655_corpus():
    # Use the same frozen transcript cache as V6.52. No Tiingo / universe / replay.
    if '_v652_corpus' in globals(): return _v652_corpus()
    if '_v650_corpus' in globals(): return _v650_corpus()
    if '_v649_corpus' in globals(): return _v649_corpus()
    if '_v648_corpus' in globals(): return _v648_corpus()
    return []

V655_MARKET_ANCHORS=[
 'market condition','market environment','general market','uptrend','correction','distribution',
 'follow through','follow-through','exposure','bull market','bear market',
 '市場','大市','牛市','熊市','回調','修正','分配日','曝險','倉位','持倉'
]
V655_BUY=['i would buy','i will buy','buy it','buy this','buy point','buy here','entry','enter','買入','買點']
V655_WATCH=['watch list','watchlist','watch','alert','set alert','wait','monitor','defer','hold off','留意','觀察','等待']
V655_PASS=['skip','pass','not buy','would not buy','avoid','stay away','不買','略過','放棄']
V655_REDUCE=['reduce exposure','less exposure','lower exposure','cut exposure','light exposure',
             'smaller position','smaller positions','reduce position','position size','cash position',
             'raise cash','more cash','less invested','scale back','曝險降低','降低倉位','減倉','減少持倉','提高現金']

def _v655_nearest_hit(low, terms, center):
    best=None
    for t in terms:
        s=t.lower(); start=0
        while True:
            p=low.find(s,start)
            if p<0: break
            d=abs(p-center)
            if best is None or d<best[0]: best=(d,p,t)
            start=p+max(1,len(s))
    return best

def _v655_semantic_label(sn, anchor_pos):
    low=sn.lower()
    hits=[]
    for label,terms in [('REDUCE_EXPOSURE',V655_REDUCE),('PASS',V655_PASS),
                        ('WATCH_DEFER',V655_WATCH),('BUY_PERMISSION',V655_BUY)]:
        h=_v655_nearest_hit(low,terms,anchor_pos)
        if h: hits.append((h[0],label,h[1],h[2]))
    if not hits:return 'UNCLEAR',None
    hits.sort(key=lambda z:z[0])
    # Explicit exposure language wins when it is reasonably local to the market anchor.
    red=[h for h in hits if h[1]=='REDUCE_EXPOSURE' and h[0] <= 1000]
    if red:return 'REDUCE_EXPOSURE',red[0][3]
    return hits[0][1],hits[0][3]

def _v655_state_tags(sn):
    low=sn.lower(); tags=[]
    checks=[
      ('UPTREND',['uptrend','confirmed uptrend','market in an uptrend','牛市','上升趨勢']),
      ('CORRECTION',['correction','market correction','回調','修正']),
      ('DISTRIBUTION',['distribution','distribution day','分配日']),
      ('BEAR',['bear market','熊市']),
      ('BULL',['bull market','牛市']),
      ('FOLLOW_THROUGH',['follow through','follow-through']),
      ('EXPOSURE',['exposure','position size','cash position','曝險','倉位','持倉'])
    ]
    for tag,terms in checks:
        if any(t.lower() in low for t in terms):tags.append(tag)
    return tags

def _v655_extract(corpus,max_cases=220):
    cases=[];seen=set()
    for row in corpus:
        text=str(row.get('text','')); low=text.lower()
        hits=[]
        for a in V655_MARKET_ANCHORS:
            start=0; aa=a.lower()
            while True:
                p=low.find(aa,start)
                if p<0:break
                hits.append((p,a)); start=p+max(1,len(aa))
        for p,a in sorted(hits):
            lo=max(0,p-1600); hi=min(len(text),p+len(a)+2400)
            sn=text[lo:hi].strip()
            local_anchor=p-lo
            label,decision_term=_v655_semantic_label(sn,local_anchor)
            key=(row.get('video_id',''), re.sub(r'\s+',' ',sn[:650]).strip(), label)
            if key in seen:continue
            seen.add(key)
            cases.append({
              'video_id':row.get('video_id',''),'title':row.get('title',''),
              'anchor':a,'semantic':label,'decision_term':decision_term or '',
              'states':_v655_state_tags(sn),'snippet':sn
            })
            if len(cases)>=max_cases:return cases
    return cases

def _v655_run():
    global v655_thread
    t0=time.time()
    try:
        _v655_write(status='running',message='从原始字幕缓存重建 Market Permission / Exposure 语义…',elapsed_sec=0,error=None)
        corpus=_v655_corpus()
        cases=_v655_extract(corpus,220)

        labels=['BUY_PERMISSION','WATCH_DEFER','REDUCE_EXPOSURE','PASS','UNCLEAR']
        summary={}
        for lab in labels:
            arr=[x for x in cases if x['semantic']==lab]
            summary[lab]={
              'cases':len(arr),'videos':len(set(x['video_id'] for x in arr if x.get('video_id'))),
              'examples':arr[:15]
            }

        states={}
        for state in ['UPTREND','CORRECTION','DISTRIBUTION','BEAR','BULL','FOLLOW_THROUGH','EXPOSURE']:
            arr=[x for x in cases if state in x['states']]
            mix={lab:sum(1 for x in arr if x['semantic']==lab) for lab in labels}
            states[state]={
              'cases':len(arr),'videos':len(set(x['video_id'] for x in arr if x.get('video_id'))),
              'mix':mix,'examples':arr[:10]
            }

        explicit=sum(summary[x]['cases'] for x in labels[:-1])
        cross=sum(1 for x in labels[:-1] if summary[x]['videos']>=2 and summary[x]['cases']>=2)
        if summary['REDUCE_EXPOSURE']['cases']>0 and summary['REDUCE_EXPOSURE']['videos']>=2:
            verdict='MARKET_EXPOSURE_SEMANTICS_SOURCE_SUPPORTED'
        elif explicit>=8 and cross>=2:
            verdict='MARKET_PERMISSION_SEMANTICS_SOURCE_SUPPORTED_EXPOSURE_LIMITED'
        else:
            verdict='MARKET_PERMISSION_SEMANTICS_INSUFFICIENT'

        res={
          'version':'V6.55 Market Permission / Exposure Semantics Reconstruction FIXED',
          'verdict':verdict,
          'transcript_videos':len(corpus),'source_cases':len(cases),'explicit_cases':explicit,
          'semantic_summary':summary,'state_ledger':states,
          'critical_point':'This corrected V6.55 reads the original cached transcript corpus directly. It does not reuse the V6.54 25-case decision-stack summary as evidence.',
          'method':'Market-context anchors locate source passages; nearby explicit language is classified as BUY_PERMISSION, WATCH_DEFER, REDUCE_EXPOSURE, PASS, or UNCLEAR. Classification is diagnostic source reconstruction only, not a trading rule.',
          'acceptance':'Only promote a market semantic to the next controlled test when it is explicit, repeats across at least 2 distinct videos, and can later be represented point-in-time without look-ahead. Do not invent a bull/bear threshold.',
          'frozen':'V6.44 TIGHT_BREAKOUT_WITH_VOLUME_CONTEXT 28.25% CAGR benchmark; -7% stop; HOLD1260; 10-slot; exits/winner management; universe. Extended branch remains closed.',
          'next_step':'If source evidence separates permission/exposure semantics, the next version maps exactly that supported semantic to existing point-in-time cached market data. If not, close Market Context as a rule branch and move to the next Actual-Buy distinction.',
          'cache_note':'Original JLaw transcript cache only; 0 Tiingo; no universe rebuild; no historical replay; no parameter tuning.'
        }
        V655_DIR.mkdir(parents=True,exist_ok=True)
        V655_RESULT.write_text(json.dumps(res,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
        _v655_write(status='done',message=f'V6.55 FIXED 完成：{verdict}',elapsed_sec=round(time.time()-t0,1),error=None)
    except Exception as ex:
        traceback.print_exc()
        _v655_write(status='error',message='V6.55 FIXED 失败',elapsed_sec=round(time.time()-t0,1),error=f'{type(ex).__name__}: {ex}')
    finally:v655_thread=None

def _v655_start():
    global v655_thread
    if _v655_alive():return False
    _v655_write(status='starting',message='V6.55 FIXED 正在启动',elapsed_sec=0,error=None)
    v655_thread=threading.Thread(target=_v655_run,daemon=True);v655_thread.start();return True

@APP.route('/v655/run',methods=['GET','POST'])
def v655_run():
    _v655_start();return redirect('/v655/market-permission-exposure')

