            body=resp.get_data(as_text=True);p=body.find('V6.58C');d=body.rfind('<div',0,p) if p>=0 else -1
            pos=d if d>=0 else body.find('<body')
            if pos>=0:body=body[:pos]+card+body[pos:]
            else:body=card+body
            resp.set_data(body);return resp
