        if hasattr(resp,'get_data'):
            body=resp.get_data(as_text=True); pos=body.find('<body')
            if pos>=0:
                gt=body.find('>',pos); body=body[:gt+1]+card+body[gt+1:] if gt>=0 else card+body
            else: body=card+body
            resp.set_data(body); return resp
